\label{intro:recollement}\label{thm:intro-main}
Under Setup~\ref{setup:standing}, there is a recollement of triangulated categories
\[
\xymatrix@C=3.5pc{
 \mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})
 \ar[r]^-{i_*}
 &
 \mathcal K_{Q}({}_A\operatorname{Inj})
 \ar@/_1.5pc/[l]_-{i^*}
 \ar@/^1.5pc/[l]^-{i^!}
 \ar[r]^-{Q_I}
 &
 \mathcal D_{Q}(A)
 \ar@/_1.5pc/[l]_-{L_I}
 \ar@/^1.5pc/[l]^-{R_I}.}
\]
 Thus
\[
 \mathcal K_{Q}({}_A\operatorname{Inj})/
 \mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})
 \simeq \mathcal D_{Q}(A).
\]

The category ${}_{Q,A}\operatorname{Mod}$ of $\Bbbk$-linear functors from $Q$ to the
 category ${}_{A}\operatorname{Mod}$ of left $A$-modules is called the \emph{category of $Q$-shaped $A$-modules}.
When $A=\Bbbk$, we write ${}_{Q}\operatorname{Mod}$ instead of ${}_{Q,\Bbbk}\operatorname{Mod}$.
The functor category ${}_{Q,A}\operatorname{Mod}$ is a Grothendieck category
with enough projectives.
Following \cite{HJ22}, we write ${}_{Q,A}\operatorname{Prj}$ and
${}_{Q,A}\operatorname{Inj}$ for its full subcategories of projective
and injective objects, respectively.
For left $A$-modules, the corresponding subcategories
are denoted by ${}_A\operatorname{Prj}$ and ${}_A\operatorname{Inj}$.
We write ${}_A\operatorname{mod}$ and ${}_A\mathrm{prj}$ for the full subcategories of finitely generated left $A$-modules and finitely generated projective left $A$-modules, respectively.
We use $\operatorname{Hom}_{Q,A}$ and $\operatorname{Ext}^i_{Q,A}$ for morphism groups
and Ext groups in ${}_{Q,A}\operatorname{Mod}$.

\begin{ipg}\label{adjoint triple}
 Recall from \cite[Corollary 3.9]{HJ22} that for every object $q$ in $Q$ there is an adjoint triple $(F_{q},E_{q},G_{q})$ as follows:
  \begin{equation*}
  \xymatrix@C=4pc{
    {}_{Q,A}\operatorname{Mod}
    \ar[r]^-{E_{q}}
    &
    {}_{A}\operatorname{Mod}
    \ar@/_1.8pc/[l]_-{F_{q}}
    \ar@/^1.8pc/[l]^-{G_{q}}
  }
  \qquad \text{given by} \qquad
  {\setlength\arraycolsep{1.5pt}
   \renewcommand{1.2}{1.2}
  \begin{array}{rcl}
  F_q(M) &=& Q(q,-) \otimes_\Bbbk M \\
  E_q(X) &=& X\mspace{1.5mu}(q) \\
  G_{q}(M) &=& \operatorname{Hom}_{\Bbbk}(Q(-, q),M)\;
  \end{array}
  }
  \end{equation*}
for $M\in {}_{A}\operatorname{Mod}$ and $X\in {}_{Q,A}\operatorname{Mod}$.
Here $E_{q}$ is the evaluation functor at $q.$
\end{ipg}

All three functors are exact
\cite[Corollary~3.9]{HJ22}.
Moreover, the objects $F_{q}(A)$, with $q\inQ$, form a set
of finitely presentable projective generators of ${}_{Q,A}\operatorname{Mod}$
\cite[Proposition~3.12]{HJ22}.


The exact adjunctions yield the following isomorphisms; see \cite[Lemma 5.1]{HJ19}.

\begin{lem}\label{lem:ext-adjunction}
For $M\in {}_{A}\operatorname{Mod}$, $X\in{}_{Q,A}\operatorname{Mod}$, and $n\geq0$, there are
natural isomorphisms
\[
\begin{aligned}
 \operatorname{Ext}^n_{Q,A}(F_q(M),X)&\cong\operatorname{Ext}^n_A(M,X(q)),\\
 \operatorname{Ext}^n_{Q,A}(X,G_q(M))&\cong\operatorname{Ext}^n_A(X(q),M).
\end{aligned}
\]
\end{lem}

Following \cite[Definition~7.9]{HJ22}, the left and right stalks
at $q\inQ$ are
\[
 S\langle q\rangle=Q(q,-)/\mathfrak r(q,-)\in{}_{Q}\operatorname{Mod}
 \qquad\text{and}\qquad S\{q\}=Q(-,q)/\mathfrak r(-,q)\in\operatorname{Mod}_{Q}.
\]
Recall from \cite[Proposition 7.15]{HJ22} that for every object $q$ in $Q$, there is an adjoint triple $(C_{q},S_{q},K_{q})$ as follows:
  \begin{equation*}
  \xymatrix@C=4pc{
    {}_{A}\operatorname{Mod}
    \ar[r]^-{S_{q}}
    &
    {}_{Q,A}\operatorname{Mod}
    \ar@/_1.8pc/[l]_-{C_{q}}
    \ar@/^1.8pc/[l]^-{K_{q}}
  }
  \qquad \text{given by} \qquad
  {\setlength\arraycolsep{1.5pt}
   \renewcommand{1.2}{1.2}
  \begin{array}{rcl}
  C_q(X) &=& S\{q\} \otimes_Q X \\
  S_q(M) &=& S\langle q\rangle\otimes_\Bbbk M \\
  K_{q}(X) &=& \operatorname{Hom}_{Q}(S\langle q\rangle,X)\;
  \end{array}
  }
  \end{equation*}
for $M\in {}_{A}\operatorname{Mod}$ and $X\in {}_{Q,A}\operatorname{Mod}$.
In particular, the stalk functor $S_{q}$ is exact.

\label{adjoint triple}
 Recall from \cite[Corollary 3.9]{HJ22} that for every object $q$ in $Q$ there is an adjoint triple $(F_{q},E_{q},G_{q})$ as follows:
  \begin{equation*}
  \xymatrix@C=4pc{
    {}_{Q,A}\operatorname{Mod}
    \ar[r]^-{E_{q}}
    &
    {}_{A}\operatorname{Mod}
    \ar@/_1.8pc/[l]_-{F_{q}}
    \ar@/^1.8pc/[l]^-{G_{q}}
  }
  \qquad \text{given by} \qquad
  {\setlength\arraycolsep{1.5pt}
   \renewcommand{1.2}{1.2}
  \begin{array}{rcl}
  F_q(M) &=& Q(q,-) \otimes_\Bbbk M \\
  E_q(X) &=& X\mspace{1.5mu}(q) \\
  G_{q}(M) &=& \operatorname{Hom}_{\Bbbk}(Q(-, q),M)\;
  \end{array}
  }
  \end{equation*}
for $M\in {}_{A}\operatorname{Mod}$ and $X\in {}_{Q,A}\operatorname{Mod}$.
Here $E_{q}$ is the evaluation functor at $q.$

\label{lem:ext-adjunction}
For $M\in {}_{A}\operatorname{Mod}$, $X\in{}_{Q,A}\operatorname{Mod}$, and $n\geq0$, there are
natural isomorphisms
\[
\begin{aligned}
 \operatorname{Ext}^n_{Q,A}(F_q(M),X)&\cong\operatorname{Ext}^n_A(M,X(q)),\\
 \operatorname{Ext}^n_{Q,A}(X,G_q(M))&\cong\operatorname{Ext}^n_A(X(q),M).
\end{aligned}
\]

A \emph{recollement} of triangulated categories is a diagram
of exact functors
\[
\xymatrix@C=3.5pc{
 \mathcal T'
 \ar[r]^-{i_*}
 &
 \mathcal T
 \ar@/_1.5pc/[l]_-{i^*}
 \ar@/^1.5pc/[l]^-{i^!}
 \ar[r]^-{j^*}
 &
 \mathcal T''
 \ar@/_1.5pc/[l]_-{j_!}
 \ar@/^1.5pc/[l]^-{j_*}
}
\]
such that:
\begin{enumerate}
\item
$(i^*,i_*,i^!)$ and $(j_!,j^*,j_*)$ are adjoint triples;
\item
$i_*$, $j_!$, and $j_*$ are fully faithful;
\item
$\mathrm{Im} i_*=\operatorname{Ker} j^{*}.$
\end{enumerate}

\label{dfn:contractible-Q-module}
An object $X\in{}_{Q,A}\operatorname{Mod}$ is called \emph{contractible} if it
satisfies the equivalent conditions of Proposition~\ref{prp:contractible}. We denote the full subcategory of contractible objects by $\operatorname{Ctr}_{Q}(A)$.

\label{cor:contractible-stable-zero}
For an object $X\in{}_{Q,A}\operatorname{Mod}$, the following conditions
are equivalent:
\begin{eqc}
\item $X$ is contractible;
\item $X\cong0$ in $\mathcal K_{Q}(A)$;
\item $\mathrm{Id}_X$ factors through a contractible object.
\end{eqc}
The class $\operatorname{Ctr}_{Q}(A)$ of contractible
objects is closed under direct summands, and
\[
 \mathcal K_{Q}(A)\simeq{}_{Q,A}\operatorname{Mod}_{\mathrm{os}}/[\operatorname{Ctr}_{Q}(A)],
\]
where $[\operatorname{Ctr}_{Q}(A)]$ denotes the ideal
of morphisms factoring through contractible objects.

\label{prp:right-adjoint}
There is an adjunction
\[
 \xymatrix@C=4pc{
 \mathcal K_{Q}({}_A\operatorname{Inj})\ar@<0.7ex>[r]^{Q_I}&
 \mathcal D_{Q}(A)\ar@<0.7ex>[l]^{R_I},}
\]
where the upper arrow is the left adjoint, and the functor $R_I$ is fully
faithful.

\cite{Bondarko}
Let $\mathcal{D}$ be a triangulated category. A \emph{$t$-structure} in $\mathcal{D}$ is a pair $(\mathcal{X}, \mathcal{Y})$ of full subcategories satisfying the following properties:
\begin{enumerate}
\item $\mathrm{Hom}_{\mathcal{D}}(X [1],Y)=0$ for all $X\in\mathcal{X}$ and $Y\in\mathcal{Y};$
\item $\mathcal{X}[1]\subseteq\mathcal{X}$ (or $\mathcal{Y}[-1]\subseteq\mathcal{Y}$);
\item For each $M\in \mathcal{D}$, there is a triangle $X[1]\to M\to Y\to X[2]$
with $X\in \mathcal{X}$ and $Y\in \mathcal{Y}.$
\end{enumerate}
A $t$-structure $(\mathcal{X},\mathcal{Y})$ is called a \emph{Bousfield localizing pair} if $\mathcal{X}$ is a triangulated subcategory of $\mathcal{D}.$ Such pairs are also called semi-orthogonal decompositions.

\label{thm:recollement}
Under Setup~\ref{setup:standing}, the inclusion $i_*:\mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})\to\mathcal K_{Q}({}_A\operatorname{Inj})$
and $Q_I$ extend to a recollement of triangulated categories
\[
\xymatrix@C=3.1pc{
 \mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})\ar[r]^{i_*}&
 \mathcal K_{Q}({}_A\operatorname{Inj})\ar@/_1.5pc/[l]_-{i^*}\ar@/^1.5pc/[l]^-{i^!}
 \ar[r]^{Q_I}&
 \mathcal D_{Q}(A)\ar@/_1.5pc/[l]_-{L_I}\ar@/^1.5pc/[l]^-{R_I}.}
\]
Moreover, $\mathcal K_{Q}({}_A\operatorname{Inj})/\mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})\simeq\mathcal D_{Q}(A)$ and $\mathcal K_{Q}({}_A\operatorname{Inj})/\operatorname{Im} L_I\simeq\mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})$.

\label{lem:locally-noetherian}
The category ${}_{Q,A}\operatorname{Mod}$ is locally noetherian. For
$M\in{}_{Q,A}\operatorname{Mod}$, the following conditions are equivalent:
\begin{eqc}
\item $M$ is noetherian;
\item $M$ is finitely generated;
\item $M$ is finitely presented;
\item $\operatorname{supp} M=\{q\in Q \mid M(q)\neq 0\}$ is finite and each $M(q)$ is finitely generated over $A$.
\end{eqc}
Every such $M$ admits an exact sequence
\begin{equation*}
 0\longrightarrow K\longrightarrow P\longrightarrow M
 \longrightarrow0,
\end{equation*}
where $P$ is a finite direct sum of objects $F_{q}(A)$
and $K$ is finitely generated. Moreover,
$\operatorname{Ext}^1_{Q,A}(M,-)$ preserves coproducts.

\label{prp:Hom-Ext-rho}
Let $M\in{}_{Q,A}\operatorname{Mod}$ and $X\in \mathscr I$. Then there is a natural isomorphism
\begin{equation*}
 \operatorname{Hom}_{\mathcal K_{Q}({}_A\operatorname{Inj})}(\Sigma^{-1}\rho M,X)
 \cong\operatorname{Ext}^1_{Q,A}(M,X).
\end{equation*}

\label{thm:compact-I}
Assume Setup~\ref{setup:standing} and let $A$ be left noetherian.
Choose a set $\mathcal N$ of representatives of the isomorphism
classes of noetherian objects in ${}_{Q,A}\operatorname{Mod}$ and, for each
$M\in\mathcal N$, a special $\mathscr I$-preenvelope $M\to\rho M$.
Then $\mathcal G_{\mathcal N}
 =\{\Sigma^{-1}\rho M\mid M\in\mathcal N\}$
is a set of compact generators for $\mathcal K_{Q}({}_A\operatorname{Inj})$. In particular,
\begin{equation*}
 \mathcal K_{Q}({}_A\operatorname{Inj})=\operatorname{Loc}(\mathcal G_{\mathcal N})
 \qquad\text{and}\qquad
 (\mathcal K_{Q}({}_A\operatorname{Inj}))^c=\operatorname{Thick}(\mathcal G_{\mathcal N}).
\end{equation*}

\label{thm:compact-acyclic}
Assume Setup~\ref{setup:standing} and suppose that $A$ is left
noetherian. Then $\mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})$ is compactly generated. With $\mathcal G_I$
as in Theorem~\ref{thm:stalk-generators}, one has
\begin{align*}
 \mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})=\operatorname{Loc}_{\mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})}(i^*\mathcal G_I)\quad \text{and}\quad
 (\mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj}))^c=\operatorname{Thick}_{\mathcal K_{Q}^{\mathrm{ac}}({}_A\operatorname{Inj})}(i^*\mathcal G_I).
\end{align*}
